/**
 * Clinical Safety Guardrails and Prompt Injection Defense Module
 * 
 * Enforces medical safety invariants:
 * 1. Pre-tagged critical value (panic threshold) deterministic alerts.
 * 2. Prompt injection sanitization and sandboxing of untrusted report text.
 * 3. Strict guardrails against medical diagnoses, prescriptions, and dosage advice.
 */

export const MEDICAL_DISCLAIMER =
  "Informational Notice: This report analysis is generated by an automated intelligence agent for informational purposes only. It does not formulate medical diagnoses, treatment plans, medication changes, or dosage recommendations. Always consult a qualified healthcare provider regarding your health concerns.";

export const CRITICAL_ALERT_MESSAGE =
  "CRITICAL ALERT: One or more test results fall into an urgent clinical panic threshold. This automated agent cannot interpret severity or formulate diagnoses. Please contact a qualified healthcare professional or emergency medical services immediately.";

// Clinically recognized panic/critical values
export const CRITICAL_THRESHOLDS = {
  'Potassium': {
    unit: 'mEq/L',
    criticalLow: 2.8,
    criticalHigh: 6.0
  },
  'Fasting Glucose': {
    unit: 'mg/dL',
    criticalLow: 50.0,
    criticalHigh: 400.0
  },
  'Platelets': {
    unit: 'x10^3/uL',
    criticalLow: 25.0,
    criticalHigh: 1000.0
  },
  'Sodium': {
    unit: 'mEq/L',
    criticalLow: 120.0,
    criticalHigh: 160.0
  },
  'Hemoglobin': {
    unit: 'g/dL',
    criticalLow: 6.5,
    criticalHigh: 20.0
  },
  'Calcium': {
    unit: 'mg/dL',
    criticalLow: 6.5,
    criticalHigh: 13.0
  }
};

// Adversarial prompt injection signatures
const ADVERSARIAL_PATTERNS = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s+prompt/i,
  /you\s+are\s+now\s+(a\s+)?doctor/i,
  /act\s+as\s+a\s+physician/i,
  /diagnose\s+me\s+with/i,
  /prescribe\s+(me\s+)?/i,
  /jailbreak/i,
  /dan\s+mode/i,
  /developer\s+mode/i,
  /override\s+(all\s+)?safety/i,
  /bypass\s+restrictions/i,
  /disregard\s+all\s+guidelines/i
];

// Prescriptive / diagnostic terms that trigger medical refusal
const PRESCRIPTIVE_QUERY_PATTERNS = [
  /\bwhat\s+(dose|dosage|medicine|medication|drug|pill|prescription)\b/i,
  /\bshould\s+i\s+(take|start|stop|increase|decrease|buy)\b/i,
  /\bprescribe\b/i,
  /\bdiagnose\s+me\b/i,
  /\bdo\s+i\s+have\s+(cancer|diabetes|infection|heart\s+attack|disease)\b/i,
  /\bhow\s+much\s+(amoxicillin|metformin|lipitor|insulin|ibuprofen|aspirin)\b/i,
  /\btreatment\s+plan\b/i,
  /\b(health|disease|mortality|death|heart\s+attack|stroke)?\s*risk\s+(prediction|score|percentage|probability)\b/i,
  /\bwhat\s+is\s+my\s+(exact\s+)?(risk|chance|probability)(\s+percentage)?\s+of\s+(dying|death|heart\s+attack|heart\s+disease|stroke|diabetes)\b/i,
  /\bmortality\s+risk\b/i
];

/**
 * Check if a test value breaches pre-tagged panic thresholds.
 * @param {string} canonicalTestName 
 * @param {number} numericValue 
 * @returns {boolean}
 */
export function checkIsCritical(canonicalTestName, numericValue) {
  if (numericValue === null || numericValue === undefined || isNaN(numericValue)) {
    return false;
  }

  const threshold = CRITICAL_THRESHOLDS[canonicalTestName];
  if (!threshold) return false;

  if (threshold.criticalLow !== undefined && numericValue < threshold.criticalLow) {
    return true;
  }
  if (threshold.criticalHigh !== undefined && numericValue > threshold.criticalHigh) {
    return true;
  }

  return false;
}

/**
 * Detect adversarial prompt injection attempts in raw document text.
 * @param {string} text 
 * @returns {{ isAdversarial: boolean, matchedPattern: string | null }}
 */
export function detectPromptInjection(text) {
  if (!text) return { isAdversarial: false, matchedPattern: null };

  for (const pattern of ADVERSARIAL_PATTERNS) {
    if (pattern.test(text)) {
      return {
        isAdversarial: true,
        matchedPattern: pattern.toString()
      };
    }
  }

  return { isAdversarial: false, matchedPattern: null };
}

/**
 * Check if user query is attempting to solicit diagnosis, treatment, or drug dosage.
 * @param {string} query 
 * @returns {boolean}
 */
export function isPrescriptiveOrDiagnosticQuery(query) {
  if (!query) return false;
  return PRESCRIPTIVE_QUERY_PATTERNS.some(p => p.test(query));
}

/**
 * Medical refusal message for diagnostic or treatment requests.
 */
export function getMedicalRefusalMessage() {
  return "I am an informational lab report agent and cannot provide medical diagnoses, treatment recommendations, medication alterations, or dosage advice. Please share your lab reports with a licensed healthcare physician who can assess your symptoms and medical history safely.";
}

/**
 * Wrap untrusted text from reports to enforce isolation.
 * @param {string} rawText 
 * @returns {string}
 */
export function sandboxUntrustedData(rawText) {
  // Strip out suspicious prompt injection tokens before passing to LLM context
  let sanitized = rawText || '';
  for (const pattern of ADVERSARIAL_PATTERNS) {
    sanitized = sanitized.replace(pattern, '[REDACTED_POTENTIAL_INJECTION]');
  }

  return `\n<untrusted_lab_document>\n${sanitized}\n</untrusted_lab_document>\n`;
}
